with flattened_attrs as (select id, service, host, status_code, context, coalesce(context['trace'], 'none') as trace_or_default, context['version'] as version, coalesce(context['region'], 'direct') as region_or_default, coalesce(context['version'], 'direct') as version_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier from app_logs) select *, first_value(region_or_default) ignore nulls over (order by status_code, id rows between unbounded preceding and current row) as first_known_region_or_default, lead(status_code, 2) over (partition by service order by status_code, id) as next_status_code, avg(status_code) over (partition by tier order by status_code, id rows between 3 preceding and current row) as status_code_avg_3, row_number() over (partition by host, tier order by status_code desc, id) as row_seq, lag(status_code, 1) over (partition by service, host order by status_code, id) as prev_status_code from flattened_attrs
